"""Map exported records to identifiers generated by Ren'Py itself."""

import json
import re
from pathlib import Path

from .filesystem import guard, write_json


def expectation(store, project, mode, home):
    with store.db() as db:
        rows = db.execute(
            "SELECT r.*,f.original FROM records r JOIN files f ON f.id=r.file WHERE f.project=? ORDER BY r.id",
            (project,),
        ).fetchall()
    records = []
    for row in rows:
        lines = row["original"].splitlines()
        locator = json.loads(row["locator"])
        header = next(
            (
                lines[i].strip()
                for i in range(locator["line"], -1, -1)
                if lines[i].strip().startswith("translate ")
            ),
            "",
        )
        match = re.fullmatch(r"translate studio_russian (.+):", header)
        if not match:
            raise ValueError("Не найден штатный идентификатор строки Ren’Py")
        item = dict(source=row["source"], text=row["text"])
        if match[1] == "strings":
            item["type"] = "string"
        else:
            item.update(type="dialogue", identifier=match[1])
        records.append(item)
    path = guard(Path(home) / "verify-expected.json")
    write_json(path, dict(records=records, mode=mode))
    return path
